    private static func table(for gospel: Bible.Gospel) -> [[Int]] {
        switch gospel {
        case .matthew: return matthew
        case .mark:    return mark
        case .luke:    return luke
        case .john:    return john
        }
    }

    /// Estimated verse start time in milliseconds, or 0 if unknown.
    static func startMs(gospel: Bible.Gospel, chapter: Int, verse: Int) -> Int {
        let arr = table(for: gospel)
        let chIdx = chapter - 1
        guard arr.indices.contains(chIdx) else { return 0 }
        let vIdx = verse - 1
        return arr[chIdx].indices.contains(vIdx) ? arr[chIdx][vIdx] : 0
    }

    /// Number of verses with known timestamps for a chapter (0 if unknown).
    static func verseCount(gospel: Bible.Gospel, chapter: Int) -> Int {
        let arr = table(for: gospel)
        let chIdx = chapter - 1
        guard arr.indices.contains(chIdx) else { return 0 }
        return arr[chIdx].count
    }

    /// The 1-based verse currently playing for the given elapsed time (ms).
    /// Returns nil when unknown, or while the chapter announcement (책·장 이름과
    /// 소제목 낭독) before verse 1 is still playing — no verse is highlighted then.
    static func currentVerse(gospel: Bible.Gospel, chapter: Int, elapsedMs: Int) -> Int? {
        let arr = table(for: gospel)
        let chIdx = chapter - 1
        guard arr.indices.contains(chIdx) else { return nil }
        let starts = arr[chIdx]
        guard !starts.isEmpty, elapsedMs >= starts[0] else { return nil }
        var current = 1
        for (index, start) in starts.enumerated() where elapsedMs >= start {
            current = index + 1
        }
        return current
    }
}
